```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;

public class RetrieveDataFromDatabase {

    public static void main(String[] args) {
        String url = "jdbc:mysql://localhost:3306/your_database_name";
        String user = "your_username";
        String password = "your_password";
        String table = "employees";

        try (Connection connection = DriverManager.getConnection(url, user, password)) {
            Statement statement = connection.createStatement();
            String query = "SELECT * FROM " + table;
            ResultSet resultSet = statement.executeQuery(query);

            while (resultSet.next()) {
                int id = resultSet.getInt("id");
                String name = resultSet.getString("name");
                String position = resultSet.getString("position");

                System.out.println("ID: " + id + ", Name: " + name + ", Position: " + position);
            }

        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
```

Make sure to replace `your_database_name`, `your_username`, and `your_password` with your actual database credentials before running the program. This Java program connects to a MySQL database and retrieves all records from the specified `employees` table, printing out the `id`, `name`, and `position` fields for each record.
